from taf.internal.managedobject import ManagedObject  # noqa: F401
from ..templates import util

_using_template = """\
class {class_name}(ManagedObject):
    def __init__(self, {attr_name}, **kwargs):
        super({class_name}, self).__init__(**kwargs)
        self._{attr_name} = {attr_name}
        self.add_prerequisite({attr_name})

    @property
    def {attr_name}(self):
        return self._{attr_name}
"""


def Using(attr_name):
    class_name = "Using" + util.camel_case(attr_name)
    if class_name not in globals():
        class_string = _using_template.format(
            class_name=class_name,
            attr_name=attr_name)
        exec(class_string, globals())
    return globals()[class_name]
